import fs from 'node:fs/promises';
import { createRequire } from 'node:module';
import path from 'node:path';
import process from 'node:process';
import { fileURLToPath, URL } from 'node:url';

const loadFromSkill = createRequire(path.join(process.env.PW_SKILL_DIR,'package.json'));
const loadFromProject = createRequire(path.join(process.cwd(),'package.json'));
const { chromium } = loadFromSkill('playwright');
const helpers = loadFromSkill('./lib/helpers');

const ROOT = fileURLToPath(new URL('../../',import.meta.url));
const ARTIFACTS = path.join(ROOT, 'docs/würzburg/verification');
const VIEWPORTS = [
  { name:'mobile',width:390,height:844 },
  { name:'tablet',width:768,height:1024 },
  { name:'desktop',width:1440,height:1000 },
  { name:'large-desktop',width:1920,height:1080 },
  { name:'reflow-320',width:320,height:800 },
];

(async () => {
  const servers = await helpers.detectDevServers();
  const origin = process.env.TARGET_URL || servers[0];
  if (!origin) throw new Error('No local server detected');
  const manifest = JSON.parse(await fs.readFile(path.join(ROOT,'data/seeds/wuerzburg.json'),'utf8'));
  const axe = await fs.readFile(loadFromProject.resolve('axe-core/axe.min.js'),'utf8');
  const browser = await chromium.launch({headless:false});
  const results = [];
  const thirdPartyRequests = new Set();
  await fs.mkdir(ARTIFACTS,{recursive:true});
  try {
    const page = await browser.newPage();
    page.on('request',(request)=>{
      const url = new URL(request.url());
      if (url.protocol.startsWith('http') && url.origin !== new URL(origin).origin) thirdPartyRequests.add(`${url.origin}${url.pathname}`);
    });
    const selectedPaths = process.argv.find((argument)=>argument.startsWith('--pages='))?.slice(8).split(',');
    for (const viewport of VIEWPORTS) {
      await page.setViewportSize({width:viewport.width,height:viewport.height});
      for (const item of manifest.pages.filter((candidate)=>candidate.path !== 'component-lab' && (selectedPaths === undefined || selectedPaths.includes(candidate.path)))) {
        const errors = [];
        const onError = (error) => errors.push(error.message);
        page.on('pageerror',onError);
        try {
          const url = `${origin}/de/s/wuerzburg${item.path ? `/${item.path}` : ''}`;
          const response = await page.goto(url,{waitUntil:'domcontentloaded',timeout:90_000});
          await page.getByRole('heading',{level:1}).waitFor({timeout:45_000});
          await page.locator('main').waitFor({timeout:15_000});
          const text = await page.locator('body').innerText();
          const overflow = await page.evaluate(()=>globalThis.document.documentElement.scrollWidth > globalThis.innerWidth);
          await page.addScriptTag({content:axe});
          const accessibility = await page.evaluate(async()=>{
            const report = await globalThis.axe.run(globalThis.document,{runOnly:{type:'tag',values:['wcag2a','wcag2aa','wcag21aa','wcag22aa']}});
            return { violations:report.violations.map((violation)=>({id:violation.id,impact:violation.impact,description:violation.description,
              nodes:violation.nodes.map((node)=>({target:node.target,summary:node.failureSummary}))})), incomplete:report.incomplete.map((entry)=>entry.id) };
          });
          const result = {page:item.path || '/',viewport:viewport.name,status:response.status(),
            title:await page.title(),h1Count:await page.getByRole('heading',{level:1}).count(),
            mainCount:await page.getByRole('main').count(),horizontalOverflow:overflow,
            unavailableSections:(text.match(/Dieser Abschnitt ist vorübergehend nicht verfügbar/g)||[]).length,
            errors,...accessibility};
          results.push(result);
          if (['','karten','stadt-in-zahlen','buergerservice/termine'].includes(item.path) && ['desktop','reflow-320'].includes(viewport.name)) {
            await page.screenshot({path:path.join(ARTIFACTS,`${item.path.replaceAll('/','-') || 'home'}-${viewport.name}.png`),fullPage:true});
          }
          process.stdout.write(`${viewport.name} ${item.path || '/'}: HTTP ${result.status}; axe ${result.violations.length}; overflow ${overflow}; unavailable ${result.unavailableSections}\n`);
        } catch (error) {
          results.push({page:item.path || '/',viewport:viewport.name,error:error.message});
          process.stdout.write(`${viewport.name} ${item.path || '/'}: ${error.message.slice(0,180)}\n`);
        } finally {
          page.off('pageerror',onError);
        }
        await fs.writeFile(path.join(ARTIFACTS,selectedPaths === undefined ? 'browser-suite.json' : 'browser-recheck.json'),`${JSON.stringify({capturedAt:new Date().toISOString(),origin,thirdPartyRequests:[...thirdPartyRequests],results},null,2)}\n`);
      }
    }
    const failed = results.filter((result)=>result.error || result.status !== 200 || result.h1Count !== 1 || result.mainCount !== 1 || result.horizontalOverflow || result.unavailableSections > 0 || result.violations?.length || result.errors?.length);
    process.stdout.write(`Completed ${results.length} page/viewport checks; ${failed.length} failures; ${thirdPartyRequests.size} third-party requests.\n`);
    if (failed.length || thirdPartyRequests.size) process.exitCode = 1;
  } finally {
    await browser.close();
  }
})().catch((error)=>{process.stderr.write(`${error.stack}\n`);process.exitCode=1;});

import { createHash } from 'node:crypto';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import process from 'node:process';
import { URL } from 'node:url';

const WATER_CATEGORY = 'Main und Gewässer';

const ROOT = new URL('../../', import.meta.url);
const SITE = '/de/s/wuerzburg';
const EPOCH = '2026-11-06T08:00:00.000Z';
const readJson = async (path) => JSON.parse(await readFile(new URL(path, ROOT), 'utf8'));
const provenance = (sourceId, kind = 'synthetic', extra = {}) => ({
  kind, sourceId, sourceUrl: null, fetchedAt: EPOCH, validUntil: null,
  license: null, licenseUrl: null, attribution: null, ...extra,
});
const sources = [];
const datasets = [];
const dataId = (key) => `wuerzburg-dataset-${key}`;
function dataset(key, name, kind, records, evidence = provenance(`wuerzburg-${key}`), fields = null) {
  sources.push({ id: `wuerzburg-source-${key}`, name: `${evidence.kind === 'synthetic' ? 'Synthetisch' : 'Momentaufnahme'}: ${name}`, kind: 'MOCK',
    config: { schemaVersion: 1, records: records.map((record) => ({ ...record, _provenance: evidence })), provenance: evidence,
      windowPolicy:{schemaVersion:1,maxRecords:kind==='GeoFeature'?10000:1000,maxOffset:100000,orderBy:kind==='SmartCityObservation'?{field:'observedAt',direction:'desc'}:null} } });
  const keys = fields ?? [...new Set(records.flatMap((record) => Object.keys(record)))].filter((field) => !['id','_provenance'].includes(field));
  datasets.push({ id: dataId(key), sourceId: `wuerzburg-source-${key}`, name, slug: key, canonicalKind: kind,
    mapping: { fields: keys.map((field) => ({ sourcePath: field, targetPath: field, required: false })) } });
  return dataId(key);
}

const pegel = await readJson('data/fixtures/pegel-main/response.json');
const pegelCapture = await readJson('data/fixtures/pegel-main/response.meta.json');
const station = pegel.find((item) => item.longname === 'WÜRZBURG');
if (!station) throw new Error('Recorded PEGELONLINE response has no Würzburg station');
const gaugeSeries = station.timeseries.find((series) => series.shortname === 'W');
if (!gaugeSeries?.currentMeasurement) throw new Error('Recorded Würzburg station has no water-level observation');
const pegelEvidence = provenance('pegel-main', 'snapshot', {
  sourceUrl: pegelCapture.url, fetchedAt: pegelCapture.fetchedAt, license: 'Datenlizenz Deutschland – Zero – Version 2.0',
  licenseUrl: 'https://www.govdata.de/dl-de/zero-2-0', attribution: 'Quelle: PEGELONLINE / Wasserstraßen- und Schifffahrtsverwaltung des Bundes',
});
// The licence must have been captured and reviewed before this manifest can be seeded.
const observation = gaugeSeries.currentMeasurement;
dataset('water-level', 'Main: Pegel Würzburg', 'SmartCityMetric', [{ id: station.uuid,
  label: `Main · ${station.longname}`, value: observation.value, unit: gaugeSeries.unit, observedAt: new Date(observation.timestamp).toISOString(), category: WATER_CATEGORY }], pegelEvidence);
dataset('gauge-locations', 'Pegel am Main', 'GeoFeature', pegel.map((item) => ({ id: item.uuid, name: item.longname,
  latitude: item.latitude, longitude: item.longitude, category: 'Pegel', description: 'Messstelle am Main; keine Hochwasserwarnung.',
  href: 'https://pegelonline.wsv.de/', })), pegelEvidence);
const history = await readJson('data/fixtures/pegel-wuerzburg-day/response.json');
const historyCapture = await readJson('data/fixtures/pegel-wuerzburg-day/response.meta.json');
dataset('water-history', 'Main: Wasserstand im Tagesverlauf', 'SmartCityObservation', history.map((point) => ({
  id: `pegel-${point.timestamp}`, series: 'Main · Pegel Würzburg', observedAt: new Date(point.timestamp).toISOString(),
  value: point.value, unit: gaugeSeries.unit, category: WATER_CATEGORY,
})), { ...pegelEvidence, sourceId: 'pegel-wuerzburg-day', sourceUrl: historyCapture.url, fetchedAt: historyCapture.fetchedAt });

